function.arguments:
{"command": "cd /workspace/out && python3 - <<'EOF'
import re
qa = re.sub(r'<!--.*?-->', '', open('staff_qa.md').read(), flags=re.S)
parts = re.split(r'\n\n(?=\*\*Q\d\.)', qa)
for p in parts:
    m = re.match(r'\*\*Q(\d)\..*?\n\n(.*)', p, flags=re.S)
    if m:
        ans = m.group(2).strip()
        print(f"Q{m.group(1)} answer-only: {len(ans.split())} words ->", "OK" if len(ans.split())<=120 else "FAIL")
EOF"}
